"""Experimental independent LG interface. No credentials or HAR data are embedded."""


def html():
    return r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Belet — тест</title><style>
*{box-sizing:border-box}body{margin:0;background:#101116;color:#fff;font:22px Arial,sans-serif}header{padding:24px 4%;background:#171820;display:flex;align-items:center;gap:25px}header strong{font-size:32px}header span{color:#9da5b1;font-size:17px}main{padding:28px 4% 80px}button{border:2px solid #555;background:#292b35;color:#fff;border-radius:8px;font-size:19px;padding:13px 18px;cursor:pointer}button:focus{outline:4px solid #fff;outline-offset:2px}#status{padding:20px;background:#22242d;border-radius:8px;line-height:1.5;max-width:1200px}h2{font-size:27px;margin:35px 0 15px}.row{display:flex;gap:18px;overflow-x:auto;padding:8px}.item{flex:0 0 190px;background:#22242d;text-align:left;padding:0;overflow:hidden}.item img{width:190px;height:270px;object-fit:cover;display:block;background:#383a43}.item span{display:block;min-height:65px;padding:9px;white-space:normal;font-size:16px}.actions{display:flex;gap:14px;margin-top:20px}.note{color:#aab2c0;font-size:16px;line-height:1.5;max-width:1100px}</style></head>
<body><header><strong>Belet</strong><span>НЕОФИЦИАЛЬНЫЙ ТЕСТ ДЛЯ LG · НЕ ПОЛНАЯ ВЕРСИЯ</span></header>
<main><div id="status" role="status">Пробуем получить каталог Belet…</div><div class="actions"><button id="retry">Повторить загрузку</button><button id="official">Открыть официальный сайт</button></div><p class="note">Запрос выполняется непосредственно с телевизора к Belet. Вход и просмотр фильмов в тестовом интерфейсе пока не реализованы. Кнопка сайта открывает обычный belet.tm и может иметь ту же ошибку, что и браузер ТВ.</p><div id="rows"></div></main>
<script>
(function(){'use strict';
var endpoint='https://homepage.belet.me/api/v2/home_page?type_id=1&h_limit=12&limit=3&offset=0';
var status=document.getElementById('status'), rows=document.getElementById('rows'), retry=document.getElementById('retry');
function say(t){status.textContent=t}
function text(v){return typeof v==='string'?v:''}
function image(item){var i=item.images||{},v=i.vertical||{},a=v.standard||v.medium||v.default||{};return text(a.url)}
function addRow(section){if(!section||!Array.isArray(section.items)||!section.items.length)return;var box=document.createElement('section'),h=document.createElement('h2'),row=document.createElement('div');h.textContent=text(section.title_ru)||text(section.title)||'Каталог';row.className='row';section.items.forEach(function(item){var btn=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span');btn.className='item';img.alt='';var src=image(item);if(src.indexOf('https://img.belet.me/')===0)img.src=src;label.textContent=text(item.name)||'Без названия';btn.appendChild(img);btn.appendChild(label);btn.onclick=function(){say('Карточка «'+(text(item.name)||'фильм')+'». Вход и воспроизведение в этом тесте пока не реализованы.');status.scrollIntoView()};row.appendChild(btn)});box.appendChild(h);box.appendChild(row);rows.appendChild(box)}
function load(){rows.textContent='';say('Загрузка каталога Belet…');retry.disabled=true;var x=new XMLHttpRequest();x.open('GET',endpoint,true);x.timeout=15000;x.setRequestHeader('lang','ru');x.onload=function(){retry.disabled=false;if(x.status!==200){say('Каталог не загружен. Сервер Belet ответил HTTP '+x.status+'. Возможна необходимость входа.');return}try{var d=JSON.parse(x.responseText);if(d.status==='error'){say('Сервер Belet не предоставил каталог: '+(text(d.message)||'требуется авторизация'));return}var result=d.result;if(!Array.isArray(result))throw Error('unexpected');result.forEach(addRow);say(rows.childNodes.length?'Каталог получен. Выберите фильм для проверки.':'Belet вернул пустой каталог.');}catch(e){say('Ответ Belet не удалось распознать. Протокол мог измениться.')}};x.onerror=function(){retry.disabled=false;say('Не удалось получить каталог. Возможно, Belet блокирует запрос из приложения (CORS), требуется авторизация или недоступна сеть.')};x.ontimeout=function(){retry.disabled=false;say('Нет ответа Belet за 15 секунд. Проверьте сеть телевизора.')};try{x.send()}catch(e){retry.disabled=false;say('Запрос каталога не запущен: '+e.message)}}
retry.onclick=load;document.getElementById('official').onclick=function(){window.location.href='https://belet.tm/'};
document.addEventListener('keydown',function(e){var key=e.keyCode;if(key!==37&&key!==38&&key!==39&&key!==40)return;var nodes=Array.prototype.slice.call(document.querySelectorAll('button:not([disabled])')),current=document.activeElement.getBoundingClientRect(),best=null,score=Infinity;nodes.forEach(function(n){if(n===document.activeElement)return;var r=n.getBoundingClientRect(),dx=(r.left+r.right-current.left-current.right)/2,dy=(r.top+r.bottom-current.top-current.bottom)/2;if((key===37&&dx>=-5)||(key===39&&dx<=5)||(key===38&&dy>=-5)||(key===40&&dy<=5))return;var s=(key===37||key===39)?Math.abs(dx)+Math.abs(dy)*2:Math.abs(dy)+Math.abs(dx)*2;if(s<score){score=s;best=n}});if(best){best.focus();e.preventDefault()}});retry.focus();load();
})();</script></body></html>'''
